const datos = $('Worker 2 - Registro').first().json.output?.datos || {};
const registros = $input.all()
  .map(item => item.json)
  .filter(item => item.ID && item.Expediente);

function normalizar(valor) {
  return String(valor ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '')
    .trim();
}

function fechaValida(valor) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(valor)) return false;

  const fecha = new Date(valor + 'T00:00:00Z');

  return !isNaN(fecha.getTime()) &&
    fecha.toISOString().slice(0, 10) === valor;
}

function rechazar(motivo) {
  return [{
    json: {
      autorizado: false,
      estado: 'rechazado',
      motivo,
      registrado: false
    }
  }];
}

// 1. Validación de campos obligatorios
const obligatorios = [
  'Expediente',
  'Materia',
  'Estado_procesal',
  'Tarea_pendiente',
  'Responsable',
  'Prioridad',
  'Estado_tarea',
  'Fecha_vencimiento'
];

const faltantes = obligatorios.filter(
  campo => !String(datos[campo] ?? '').trim()
);

if (faltantes.length > 0) {
  return rechazar(
    'Faltan campos obligatorios: ' + faltantes.join(', ')
  );
}

// 2. Validación de valores permitidos
const materias = [
  'Civil', 'Comercial', 'Laboral', 'Consumo', 'Sucesorio'
];

const prioridades = ['Alta', 'Media', 'Baja'];

const estados = ['Pendiente', 'En curso', 'Completada'];

if (!materias.includes(datos.Materia)) {
  return rechazar('Materia jurídica no permitida.');
}

if (!prioridades.includes(datos.Prioridad)) {
  return rechazar('Prioridad no permitida.');
}

if (!estados.includes(datos.Estado_tarea)) {
  return rechazar('Estado de tarea no permitido.');
}

// 3. Validación de fechas
if (!fechaValida(datos.Fecha_vencimiento)) {
  return rechazar('Fecha de vencimiento inválida.');
}

if (
  datos.Ultima_actuacion &&
  !fechaValida(datos.Ultima_actuacion)
) {
  return rechazar('Fecha de última actuación inválida.');
}

// 4. Comprobación de duplicados
const duplicado = registros.find(
  registro =>
    normalizar(registro.Expediente) ===
    normalizar(datos.Expediente)
);

if (duplicado) {
  return rechazar(
    'El expediente ya existe con ID ' + duplicado.ID
  );
}

// 5. Generación del siguiente identificador
const numeros = registros
  .map(r => /^EXP-(\d+)$/i.exec(String(r.ID)))
  .filter(Boolean)
  .map(match => Number(match[1]));

const siguiente = Math.max(0, ...numeros) + 1;
const nuevoID = 'EXP-' + String(siguiente).padStart(3, '0');

// 6. Resultado aprobado
return [{
  json: {
    autorizado: true,
    estado: 'aprobado',
    motivo: 'Validación técnica satisfactoria.',
    registrado: false,
    id: nuevoID,
    datos: {
      ID: nuevoID,
      ...datos,
      Ultima_actuacion: datos.Ultima_actuacion || '',
      Observaciones: datos.Observaciones || ''
    }
  }
}];
